# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import Iterable, List

from rosterkit.models import Student

def _require_contacts(students: List[Student]) -> None:
    if not students:
        raise ValueError("no students to list on the contact sheet")
    for student in students:
        if not student.email:
            raise ValueError(f"no email for student {student.display_name}")

def _width(values: Iterable[str]) -> int:
    return max(len(value) for value in values)

def _row(student: Student, name_w: int, sect_w: int) -> str:
    name = f"{student.display_name:<{name_w}}"
    return f"{name}  {student.section:<{sect_w}}  {student.email}"

# ---
def contact_rows(students: Iterable[Student]) -> List[str]:
    """Rows of name, section and email in aligned columns, sorted by name."""
    ordered = sorted(students, key=lambda student: student.display_name)
    _require_contacts(ordered)
    name_w = _width(student.display_name for student in ordered)
    sect_w = _width(student.section for student in ordered)
    return [_row(student, name_w, sect_w) for student in ordered]

