# owner: platform
import unittest

from rosterkit.contacts import contact_rows
from rosterkit.models import Student

def make(last, first, section="A", email="x@example.org"):
    return Student("1", last, first, section, email)

class ContactRowsTests(unittest.TestCase):
    def test_rows_are_sorted_by_name(self):
        rows = contact_rows([make("Zed", "Al"), make("Abe", "Bo")])
        self.assertTrue(rows[0].startswith("Abe, Bo"))
        self.assertTrue(rows[1].startswith("Zed, Al"))

    def test_columns_line_up(self):
        rows = contact_rows([
            make("Li", "Al", "A", "a@example.org"),
            make("Longname", "Bo", "B10", "b@example.org")
        ])
        self.assertEqual(rows[0].index("a@"), rows[1].index("b@"))
        self.assertEqual(rows[0].index("A "), rows[1].index("B10"))

    def test_missing_email_names_the_student(self):
        with self.assertRaises(ValueError) as caught:
            contact_rows([make("Abe", "Bo"), make("Cruz", "Di", email=None)])
        self.assertIn("Cruz, Di", str(caught.exception))

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            contact_rows([])

if __name__ == "__main__":
    unittest.main()
